//! Emits `desktop/web/src/generated/locale-registry.ts` and
//! `desktop/src/db/query_builder/translate_value.rs` from
//! `canopi_types::locale::LOCALES` (L6, contracts §14).

use std::error::Error;
use std::fmt::Write;

use canopi_types::locale::{LOCALES, LocaleSpec};
use canopi_types::settings::Locale;

pub(crate) fn render_locale_registry_ts() -> Result<String, Box<dyn Error>> {
    let mut out = String::new();
    writeln!(
        out,
        "// Generated by `cargo run -p bindings-gen` from `canopi-types/src/locale.rs`."
    )?;
    writeln!(out, "// Do not edit by hand.")?;
    writeln!(out)?;
    writeln!(out, "import type {{ Locale }} from './contracts'")?;
    writeln!(out)?;
    writeln!(
        out,
        "export type PluralCategory = 'zero' | 'one' | 'two' | 'few' | 'many' | 'other'"
    )?;
    writeln!(out)?;
    writeln!(out, "export interface LocaleSpec {{")?;
    writeln!(out, "  readonly code: Locale")?;
    writeln!(out, "  readonly bcp47: string")?;
    writeln!(out, "  readonly endonym: string")?;
    writeln!(out, "  readonly catalogColumn: string")?;
    writeln!(out, "  readonly weekStartFallback: 0 | 1")?;
    writeln!(
        out,
        "  readonly pluralCategories: readonly PluralCategory[]"
    )?;
    writeln!(out, "}}")?;
    writeln!(out)?;
    writeln!(
        out,
        "export const LOCALE_REGISTRY: readonly LocaleSpec[] = ["
    )?;
    for spec in LOCALES {
        write_ts_locale_spec(&mut out, spec)?;
    }
    writeln!(out, "] as const")?;
    writeln!(out)?;
    let codes = LOCALES
        .iter()
        .map(|spec| format!("'{}'", spec.code))
        .collect::<Vec<_>>()
        .join(", ");
    writeln!(
        out,
        "export const SUPPORTED_LOCALES = [{codes}] as const satisfies readonly Locale[]"
    )?;
    writeln!(out)?;
    writeln!(
        out,
        "export const LOCALE_BY_CODE: Readonly<Record<Locale, LocaleSpec>> = {{"
    )?;
    for (idx, spec) in LOCALES.iter().enumerate() {
        writeln!(out, "  {}: LOCALE_REGISTRY[{idx}]!,", spec.code)?;
    }
    writeln!(out, "}}")?;
    writeln!(out)?;
    writeln!(
        out,
        "export const LOCALE_WEEK_START_FALLBACK: Readonly<Record<Locale, 0 | 1>> = {{"
    )?;
    for spec in LOCALES {
        writeln!(
            out,
            "  {}: {},",
            spec.code,
            spec.week_start_fallback.js_day()
        )?;
    }
    writeln!(out, "}}")?;
    writeln!(out)?;
    write_ts_locale_matcher(&mut out)?;
    Ok(out)
}

fn write_ts_locale_matcher(out: &mut String) -> Result<(), Box<dyn Error>> {
    writeln!(
        out,
        "/** First-run language matcher (contracts §14, 2.1-Q345): returns the first tag whose primary subtag matches a registered locale. */"
    )?;
    writeln!(
        out,
        "export function matchLocale(tags: readonly (string | null | undefined)[]): Locale | null {{"
    )?;
    writeln!(out, "  for (const tag of tags) {{")?;
    writeln!(out, "    if (!tag) continue")?;
    writeln!(
        out,
        "    const primary = tag.trim().split(/[-_.]/)[0]?.toLowerCase() ?? ''"
    )?;
    writeln!(
        out,
        "    if (Object.prototype.hasOwnProperty.call(LOCALE_BY_CODE, primary)) {{"
    )?;
    writeln!(out, "      return primary as Locale")?;
    writeln!(out, "    }}")?;
    writeln!(out, "  }}")?;
    writeln!(out, "  return null")?;
    writeln!(out, "}}")?;
    writeln!(out)?;
    writeln!(
        out,
        "/** Like `matchLocale`, falling back to `'en'` when no tag matches. */"
    )?;
    writeln!(
        out,
        "export function matchLocaleOrDefault(tags: readonly (string | null | undefined)[]): Locale {{"
    )?;
    writeln!(out, "  return matchLocale(tags) ?? 'en'")?;
    writeln!(out, "}}")?;
    Ok(())
}

fn write_ts_locale_spec(out: &mut String, spec: &LocaleSpec) -> Result<(), Box<dyn Error>> {
    let endonym = serde_json::to_string(spec.endonym)?;
    let plurals = spec
        .plural_categories
        .iter()
        .map(|cat| format!("'{}'", cat.as_str()))
        .collect::<Vec<_>>()
        .join(", ");
    writeln!(out, "  {{")?;
    writeln!(out, "    code: '{}',", spec.code)?;
    writeln!(out, "    bcp47: '{}',", spec.bcp47)?;
    writeln!(out, "    endonym: {endonym},")?;
    writeln!(out, "    catalogColumn: '{}',", spec.catalog_column)?;
    writeln!(
        out,
        "    weekStartFallback: {},",
        spec.week_start_fallback.js_day()
    )?;
    writeln!(out, "    pluralCategories: [{plurals}],")?;
    writeln!(out, "  }},")?;
    Ok(())
}

pub(crate) fn render_translate_value_rust() -> Result<String, Box<dyn Error>> {
    let mut out = String::new();
    writeln!(
        out,
        "// Generated by `cargo run -p bindings-gen` from `canopi-types/src/locale.rs`."
    )?;
    writeln!(out, "// Do not edit by hand.")?;
    writeln!(out)?;
    writeln!(out, "use canopi_types::settings::Locale;")?;
    writeln!(out)?;
    writeln!(
        out,
        "/// Static `translated_values` lookup query for a non-English locale (contracts §14)."
    )?;
    writeln!(
        out,
        "/// Returns `None` for `Locale::En`, where the source English value needs no lookup."
    )?;
    writeln!(
        out,
        "pub(crate) const fn translate_value_sql(locale: Locale) -> Option<&'static str> {{"
    )?;
    writeln!(out, "    match locale {{")?;
    for spec in LOCALES {
        let variant = locale_variant_name(spec.locale);
        if spec.locale == Locale::En {
            writeln!(out, "        Locale::{variant} => None,")?;
        } else {
            writeln!(
                out,
                "        Locale::{variant} => Some(\"SELECT {} FROM translated_values WHERE field_name = ?1 AND value_en = ?2 LIMIT 1\"),",
                spec.catalog_column
            )?;
        }
    }
    writeln!(out, "    }}")?;
    writeln!(out, "}}")?;
    Ok(out)
}

const fn locale_variant_name(locale: Locale) -> &'static str {
    match locale {
        Locale::En => "En",
        Locale::Fr => "Fr",
        Locale::Es => "Es",
        Locale::Pt => "Pt",
        Locale::It => "It",
        Locale::Zh => "Zh",
        Locale::De => "De",
        Locale::Ja => "Ja",
        Locale::Ko => "Ko",
        Locale::Nl => "Nl",
        Locale::Ru => "Ru",
    }
}
